public class SecureLogReader {
    public String readFirstLine(String path) throws Exception {
        // Multiple resources: br2 is closed first, then br1
        try (BufferedReader br1 = new BufferedReader(new FileReader(path));
             BufferedReader br2 = new BufferedReader(new StringReader("fallback"))) {

            String line = br1.readLine();
            if (line == null) {
                return br2.readLine();
            }
            return line;
        } 
        // Compiler automatically appends hidden finally block handling close() and suppressed exceptions
    }
}
